(async () => {
  const btn = document.querySelector('.hero .btn[data-quote-open]');
  if (!btn) return {error: 'no hero button'};
  btn.click();
  await new Promise(r => setTimeout(r, 500));
  const m = document.getElementById('gquote');
  const r = m ? m.getBoundingClientRect() : null;
  return {opened: m ? !m.hidden : null, w: r ? Math.round(r.width) : 0,
          heading: document.getElementById('gq-title') ? document.getElementById('gq-title').textContent : '',
          fields: [...m.querySelectorAll('input,select,textarea')].map(f => f.name).filter(Boolean),
          waFloat: !!document.querySelector('.wa-float')};
})()
